test:
it = ListIterator(['a', 'b'])
assert iter(it) is it
assert next(it) == 'a'
assert it.next() == 'b'
try:
    next(it)
    assert False, 'expected StopIteration'
except StopIteration:
    pass
assert it.get_state() == {'index': 2}

def drain(iterator):
    out = []
    while True:
        try:
            out.append(iterator.next())
        except StopIteration:
            return out

data = ['a', 'b', 'c']
it = ListIterator(data)
states = []
while True:
    states.append(it.get_state())
    try:
        it.next()
    except StopIteration:
        break
for state in states:
    restored = ListIterator(data)
    restored.set_state(state)
    assert drain(restored) == data[state['index']:]

items = [1, 2]
it = ListIterator(items)
items.append(3)
assert [it.next(), it.next()] == [1, 2]
for state in [{'index': -1}, {'index': 3}, {'index': 1.5}, {'index': '1'}]:
    try:
        ListIterator([1, 2]).set_state(state)
        assert False, 'expected ValueError'
    except ValueError:
        pass
